import subprocess, time, shlex, os, random
class Tmux:
    def __init__(self, cols=80, rows=24):
        self.sess="t"+str(random.randint(100000,999999))
        subprocess.run(["tmux","new-session","-d","-s",self.sess,"-x",str(cols),"-y",str(rows)], check=True)
        self.send("export BR_INSTALL=no; export HOME=/home/agent; cd /tmp/t1")
        time.sleep(0.3)
    def send(self, s):
        subprocess.run(["tmux","send-keys","-t",self.sess,s,"Enter"])
    def key(self, *keys):
        subprocess.run(["tmux","send-keys","-t",self.sess]+list(keys))
    def capture(self, esc=False):
        args=["tmux","capture-pane","-t",self.sess,"-p"]
        if esc: args.append("-e")
        return subprocess.run(args, capture_output=True, text=True).stdout
    def run(self, cmdline, wait=1.0):
        self.send(cmdline)
        time.sleep(wait)
        return self.capture()
    def kill(self):
        subprocess.run(["tmux","kill-session","-t",self.sess], capture_output=True)

def interactive(args="--color no", wait=1.0, cols=80, rows=24):
    t=Tmux(cols,rows)
    out=t.run(f"/workspace/executable {args}", wait=wait)
    return t,out

if __name__=="__main__":
    t,out=interactive()
    print(repr(out))
    print("---plain---")
    print(out)
    t.kill()
PY
python3 /tmp/probe.py
