import subprocess, os, tempfile
def fresh(args, stdin="", env_extra=None, shell=None):
    home=tempfile.mkdtemp(prefix="fh2_")
    env=dict(os.environ); env["HOME"]=home; env.pop("XDG_CONFIG_HOME",None); env.pop("BROOT_CONFIG_DIR",None)
    if shell: env["SHELL"]=shell
    if env_extra: env.update(env_extra)
    r=subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, env=env, cwd="/tmp/t1", input=stdin, timeout=5)
    print("home",home,"args",args,"stdin",repr(stdin),"shell",shell,"exit",r.returncode)
    print("OUT",repr(r.stdout))
    print("ERR",repr(r.stderr[:2000]))
    for root,dirs,fs in os.walk(home):
        for name in dirs+fs:
            p=os.path.join(root,name)
            print(" ",p, "->", os.readlink(p) if os.path.islink(p) else "")
            if os.path.isfile(p) and not os.path.islink(p):
                try: print("   content:",repr(open(p).read()[:800]))
                except: pass
    print()
