#!/usr/bin/env python3
import os, sys, re, math, stat, time, shutil, subprocess, socket, threading, json, difflib
from pathlib import Path

VERSION="1.54.0"

def resource_bytes(name):
    # name like "default_conf/conf.hjson" or "shell_funcs/bash.txt"
    # zipapp: argv0 is zip
    try:
        import zipfile
        if zipfile.is_zipfile(sys.argv[0]):
            z=zipfile.ZipFile(sys.argv[0])
            try:
                return z.read(name)
            except KeyError:
                pass
    except Exception:
        pass
    # filesystem layouts
    here=Path(__file__).resolve()
    candidates=[]
    candidates.append(here.parent/name)
    if name.startswith("default_conf/"):
        candidates.append(here.parent.parent/"resources"/"default-conf"/name[len("default_conf/"):])
        candidates.append(Path.cwd()/"resources"/"default-conf"/name[len("default_conf/"):])
    if name.startswith("shell_funcs/"):
        candidates.append(here.parent.parent/"data"/name)
        candidates.append(Path.cwd()/"data"/name)
    for c in candidates:
        try:
            if c.is_file(): return c.read_bytes()
        except Exception: pass
    return b""

def resource_text(name):
    return resource_bytes(name).decode("utf-8", errors="surrogateescape")

def default_conf_files():
    # returns dict relpath->bytes
    files={}
    names=["conf.hjson","verbs.hjson"]
    skins=["catppuccin-macchiato.hjson","catppuccin-mocha.hjson","dark-blue.hjson","dark-gruvbox.hjson","dark-orange.hjson","native-16.hjson","solarized-dark.hjson","solarized-light.hjson","white.hjson"]
    for n in names:
        b=resource_bytes("default_conf/"+n)
        if b: files[n]=b
    for n in skins:
        b=resource_bytes("default_conf/skins/"+n)
        if b: files["skins/"+n]=b
    # if in repo filesystem and zip missed some, enumerate
    if not files:
        root=Path(__file__).resolve().parent.parent/"resources"/"default-conf"
        if root.is_dir():
            for p in root.rglob("*"):
                if p.is_file(): files[str(p.relative_to(root))]=p.read_bytes()
    return files

