            try:
                return z.read(name)
            except KeyError:
                pass
    except Exception:
        pass
    # filesystem layouts
    here=Path(__file__).resolve()
    candidates=[]
    candidates.append(here.parent/name)
    if name.startswith("default_conf/"):
        candidates.append(here.parent.parent/"resources"/"default-conf"/name[len("default_conf/"):])
        candidates.append(Path.cwd()/"resources"/"default-conf"/name[len("default_conf/"):])
    if name.startswith("shell_funcs/"):
        candidates.append(here.parent.parent/"data"/name)
