def prog_name():
    p=os.path.basename(sys.argv[0]) if sys.argv and sys.argv[0] else "broot"
    return p or "broot"

def usage_generic():
    return f"Usage: {prog_name()} [OPTIONS] [ROOT]\n"
def usage_for(spec):
    if spec is None: return usage_generic()
    part=f"--{spec['long']}"
    if spec["val"] not in (None,""):
        # for help/version val is None
        part+=f" {spec['val']}"
    elif spec["key"] in ("help","version","install"):
        pass
    # value specs handled; flag specs: just --long
    return f"Usage: {prog_name()} {part} [ROOT]\n"

class ClapError(Exception):
    def __init__(self, text):
        self.text=text

def clap_fail(msg, usage_spec=None, tip=None):
    out=f"error: {msg}\n"
    if tip:
        out+=f"\n  tip: {tip}\n"
    out+=f"\n{usage_for(usage_spec)}"
    raise ClapError(out)

def similar_spec(name):
    # name without --
    candidates=[s["long"] for s in SPECS]
    # prefix match first
    pref=[c for c in candidates if c.startswith(name) or name.startswith(c)]
    if pref:
        return BY_LONG[sorted(pref, key=lambda c: (len(c),c))[0]]
    m=difflib.get_close_matches(name, candidates, n=1, cutoff=0.55)
    if m: return BY_LONG[m[0]]
    # jaro-ish via difflib on parts?
    best=None; bestr=0
    for c in candidates:
        r=difflib.SequenceMatcher(None,name,c).ratio()
        if r>bestr: bestr=r; best=c
    if bestr>0.5: return BY_LONG[best]
    return None

def validate_numeric(spec, value):
    # return int or raise clap error formatted
    s=value
    # mimic Rust u16 parser / clap ranged parser
    def invalid(reason):
        raise ClapError(f"error: invalid value '{value}' for '--{spec['long']} {spec['meta']}': {reason}\n")
    # Determine if it's integer syntax: optional +/- digits
    if re.fullmatch(r'[+-]?\d+', s or ""):
        try:
            v=int(s)
        except:
            invalid("number too large to fit in target type")
        # check magnitude for u64 parsing: if abs > 2^64-1 -> too large
        if v>18446744073709551615 or v< -9223372036854775808:
            # Rust: positive too large
            if v>=0: invalid("number too large to fit in target type")
        if v<0 or v>65535:
            invalid(f"{s} is not in 0..=65535")
        return v
    else:
        # if digits with sign huge etc handled above; empty?
        # strings like "999...a" -> invalid digit
        invalid("invalid digit found in string")

def parse_args(argv):
    opts={}
    seen={}  # key -> spec
    root=None
    i=0
    end_opts=False
    help_seen=False
    # for usage on error after --help etc: clap seems to use --help in usage if seen
    context_spec=None
    while i<len(argv):
        arg=argv[i]
        if not end_opts and arg=="--":
            end_opts=True; i+=1; continue
        if not end_opts and arg.startswith("--") and len(arg)>2:
            body=arg[2:]
            if "=" in body:
                name,value=body.split("=",1); has_eq=True
            else:
                name,value=body,None; has_eq=False
            spec=BY_LONG.get(name)
            if spec is None:
                sim=similar_spec(name)
                if sim:
                    clap_fail(f"unexpected argument '--{name}' found", usage_spec=sim, tip=f"a similar argument exists: '--{sim['long']}'")
                else:
                    clap_fail(f"unexpected argument '--{name}' found", usage_spec=context_spec, tip=f"to pass '--{name}' as a value, use '-- --{name}'")
            # duplicate
            if spec["key"] in seen:
                disp=f"--{spec['long']}" + (f" {spec['meta']}" if spec["val"] not in (None,"") else "")
                clap_fail(f"the argument '{disp}' cannot be used multiple times", usage_spec=context_spec)
            seen[spec["key"]]=spec
            if spec["key"]=="help": context_spec=spec
            if spec["key"]=="version" and context_spec is None: pass
            if spec["val"] is None or spec["val"]=="":
                # flag
                if has_eq:
                    clap_fail(f"unexpected value '{value}' for '--{spec['long']}' found; no more were expected", usage_spec=spec)
                opts[spec["key"]]=True
                i+=1; continue
            else:
                # needs value
                if has_eq:
                    if value=="":
                        msg=f"error: a value is required for '--{spec['long']} {spec['meta']}' but none was supplied\n"
                        if spec.get("possible"): msg+=f"  [possible values: {', '.join(spec['possible'])}]\n"
                        raise ClapError(msg)
                    val=value
                    i+=1
                else:
                    # next arg required; if next looks like option -> clap reports unexpected? For numeric -1 case handled in loop? Actually clap: if next starts with - and is not a value, error for that next arg as unexpected.
                    if i+1>=len(argv):
                        msg=f"error: a value is required for '--{spec['long']} {spec['meta']}' but none was supplied\n"
                        if spec.get("possible"): msg+=f"  [possible values: {', '.join(spec['possible'])}]\n"
                        raise ClapError(msg)
                    nxt=argv[i+1]
                    if nxt.startswith("-") and nxt!="-":
                        # treat as unexpected argument error for nxt (replicate --height -1 case)
                        # But some values legitimately start with - for --cmd etc? Original: --height -1 gave unexpected '-1'. For --cmd -something probably similar?
                        # Determine token name for error: up to = ?
                        disp=nxt.split("=")[0]
                        clap_fail(f"unexpected argument '{disp}' found", usage_spec=context_spec, tip=f"to pass '{disp}' as a value, use '-- {disp}'")
                    val=nxt; i+=2
                # validate possible / numeric
                if spec.get("possible") and val not in spec["possible"]:
                    msg=f"error: invalid value '{val}' for '--{spec['long']} {spec['meta']}'\n  [possible values: {', '.join(spec['possible'])}]\n"
                    raise ClapError(msg)
                if spec.get("numeric"):
                    val=validate_numeric(spec, val)
                opts[spec["key"]]=val
                continue
        elif not end_opts and arg.startswith("-") and arg!="-" and len(arg)>1:
            # short cluster
            chars=arg[1:]
            j=0
            # special: token may be like -cfoo or -c=foo
            consumed_next=False
            while j<len(chars):
                ch=chars[j]
                spec=BY_SHORT.get(ch)
                if spec is None:
                    disp=f"-{ch}"
                    clap_fail(f"unexpected argument '{disp}' found", usage_spec=context_spec, tip=f"to pass '{disp}' as a value, use '-- {disp}'")
                if spec["key"] in seen:
                    disp=f"--{spec['long']}" + (f" {spec['meta']}" if spec["val"] not in (None,"") else "")
                    clap_fail(f"the argument '{disp}' cannot be used multiple times", usage_spec=context_spec)
                seen[spec["key"]]=spec
                if spec["val"] not in (None,""):
                    # value taking short (only c)
                    rest=chars[j+1:]
                    if rest.startswith("="): rest=rest[1:]
                    if rest:
                        val=rest; i+=1
                    else:
                        if i+1>=len(argv):
                            msg=f"error: a value is required for '--{spec['long']} {spec['meta']}' but none was supplied\n"
                            if spec.get("possible"): msg+=f"  [possible values: {', '.join(spec['possible'])}]\n"
                            raise ClapError(msg)
                        nxt=argv[i+1]
                        if nxt.startswith("-") and nxt!="-":
                            disp=nxt.split("=")[0]
                            clap_fail(f"unexpected argument '{disp}' found", usage_spec=context_spec, tip=f"to pass '{disp}' as a value, use '-- {disp}'")
                        val=nxt; i+=2; consumed_next=True
                    if spec.get("possible") and val not in spec["possible"]:
                        msg=f"error: invalid value '{val}' for '--{spec['long']} {spec['meta']}'\n  [possible values: {', '.join(spec['possible'])}]\n"
                        raise ClapError(msg)
                    opts[spec["key"]]=val
                    j=len(chars)
                    break
                else:
                    opts[spec["key"]]=True
                    j+=1
            if not consumed_next:
                i+=1
            continue
        else:
            # positional
            if root is not None:
                clap_fail(f"unexpected argument '{arg}' found", usage_spec=context_spec)
            root=arg; i+=1; continue
    return opts, root

