def term_width_for_help():
    # try tty sizes from stderr/stdin/stdout//dev/tty
    for fd in [2,0,1]:
        try:
            sz=os.get_terminal_size(fd)
            if sz.columns>0: return sz.columns
        except Exception: pass
    try:
        fd=os.open("/dev/tty", os.O_RDWR)
        try:
            sz=os.get_terminal_size(fd); 
            if sz.columns>0: return sz.columns
        finally: os.close(fd)
    except Exception: pass
    return 50

def wrap_text(text, width):
    if width<=0: return [text]
    lines=[]
    for para in text.split("\n"):
        if para=="": lines.append(""); continue
        words=para.split(" ")
        cur=""
        for w in words:
            if cur=="":
                cur=w
            elif len(cur)+1+len(w)<=width:
                cur+=" "+w
            else:
                lines.append(cur)
                # long word hard split
                while len(w)>width:
                    lines.append(w[:width]); w=w[width:]
                cur=w
        lines.append(cur)
    return lines

def hard_wrap(s, width):
    if width<=0: return [s]
    if s=="": return [""]
    out=[]
    # word wrap with hard split for long tokens, preserving behaviour approx for long col (tokens)
    # For table long/short columns, original uses word wrap then hard splits long words
    words=s.split(" ")
    cur=""
    for w in words:
        if len(w)>width:
            if cur:
                lines=hard_wrap_token(cur,width); out.extend(lines); cur=""
            # split token
            while len(w)>width:
                out.append(w[:width]); w=w[width:]
            cur=w
        else:
            if cur=="": cur=w
            elif len(cur)+1+len(w)<=width: cur+=" "+w
            else: out.append(cur); cur=w
    if cur!="" or not out: out.append(cur)
    return out

def hard_wrap_token(s,width):
    return [s[i:i+width] for i in range(0,len(s),width)] or [""]

