def wrap_text(text, width):
    if width<=0: return [text]
    lines=[]
    for para in text.split("\n"):
        if para=="": lines.append(""); continue
        words=para.split(" ")
        cur=""
        for w in words:
            if cur=="":
                cur=w
            elif len(cur)+1+len(w)<=width:
                cur+=" "+w
            else:
                lines.append(cur)
                # long word hard split
                while len(w)>width:
                    lines.append(w[:width]); w=w[width:]
                cur=w
        lines.append(cur)
    return lines

def hard_wrap(s, width):
    if width<=0: return [s]
