    def __init__(self, fg=None,bg=None,bold=False,italic=False,underline=False,dim=False,reverse=False,strike=False):
        self.fg=fg; self.bg=bg; self.bold=bold; self.italic=italic; self.underline=underline; self.dim=dim; self.reverse=reverse; self.strike=strike
    def ansi_prefix(self):
        parts=[]
        if self.bold: parts.append("1")
        if self.dim: parts.append("2")
        if self.italic: parts.append("3")
        if self.underline: parts.append("4")
        if self.reverse: parts.append("7")
        if self.strike: parts.append("9")
        if self.fg is not None:
            kind,val=self.fg
            if kind=="ansi": parts.append(f"38;5;{val}")
            else: parts.append(f"38;2;{val[0]};{val[1]};{val[2]}")
        if self.bg is not None:
            kind,val=self.bg
            if kind=="ansi": parts.append(f"48;5;{val}")
            else: parts.append(f"48;2;{val[0]};{val[1]};{val[2]}")
        if not parts: return ""
        return "\x1b["+";".join(parts)+"m"
    def apply(self,text, colored=True):
        if not colored or not text: return text
        pre=self.ansi_prefix()
        if not pre: return text
        # original often emits fg then bg separate but combined equivalent for terminals
        return pre+text+"\x1b[0m"

def parse_skin_style(value):
    # value like "gray(22) none  / gray(20) none" or "ansi(110) None bold"
    if not isinstance(value,str): return Style()
    first=value.split("/")[0].strip()
    # tokens: color tokens may contain parentheses; split by whitespace
    toks=first.split()
    fg=None; bg=None; bold=italic=underline=False; dim=False
    colors=[]
    attrs=[]
    for tok in toks:
        low=tok.lower()
        if low in ("bold",): bold=True
