            v=self.parse_array()
        else:
            # root object without braces
            v=self.parse_object_body(end_char=None)
        self.skip()
        if self.i<self.n: self.err("UnexpectedChar")
        return v
    def parse_object(self):
        # at {
        self.i+=1
        return self.parse_object_body(end_char="}")
    def parse_object_body(self, end_char):
        obj={}
        while True:
            self.skip()
            if self.i>=self.n:
                if end_char: self.err("Eof")
                break
            if end_char and self.s[self.i]==end_char:
                self.i+=1; break
            # key
            key=self.parse_key()
            self.skip_inline()
            if self.i>=self.n or self.s[self.i]!=":":
                self.err("UnexpectedChar")
            self.i+=1
            val=self.parse_value()
            obj[key]=val
            # separators: commas or newline (skip handles)
            self.skip_inline()
            if self.i<self.n and self.s[self.i]==",":
                self.i+=1
        return obj
    def parse_key(self):
        self.skip_inline()
        if self.i>=self.n: self.err("Eof")
        c=self.s[self.i]
        if c in "\"'":
            return self.parse_string()
        start=self.i
        while self.i<self.n and self.s[self.i] not in ":\n,{}[]":
            self.i+=1
        return self.s[start:self.i].strip()
    def parse_string(self):
        quote=self.s[self.i]
        if self.s.startswith("'''",self.i):
            end=self.s.find("'''",self.i+3)
            if end==-1: self.err("Eof")
            v=self.s[self.i+3:end]; self.i=end+3; return v
        self.i+=1
        out=""
        while self.i<self.n:
            c=self.s[self.i]
            if c==quote:
                self.i+=1; return out
            if quote=='"' and c=="\\":
                self.i+=1
                if self.i>=self.n: break
                e=self.s[self.i]
                mp={'n':'\n','t':'\t','r':'\r','b':'\b','f':'\f','\\':'\\','/':'/', '"':'"', "'":"'"}
                if e=='u':
                    out+=chr(int(self.s[self.i+1:self.i+5],16)); self.i+=5; continue
                out+=mp.get(e,e); self.i+=1; continue
            out+=c; self.i+=1
        self.err("Eof")
    def parse_array(self):
        self.i+=1; arr=[]
        while True:
            self.skip()
            if self.i>=self.n: self.err("Eof")
            if self.s[self.i]=="]":
                self.i+=1; break
            arr.append(self.parse_value())
            self.skip_inline()
            if self.i<self.n and self.s[self.i]==",":
                self.i+=1
        return arr
    def parse_value(self):
        self.skip()
        if self.i>=self.n: self.err("Eof")
        c=self.s[self.i]
        if c=="{": return self.parse_object()
        if c=="[": return self.parse_array()
        if c in "\"'": return self.parse_string()
        # bare value until newline or ',' or closing chars, but objects/arrays multiline handled above.
        # In an array/object context, comma or } ] or newline ends. Quoteless strings may include spaces.
        start=self.i
        line_start=self.i
        while self.i<self.n and self.s[self.i] not in "\n,}]":
            # comments start? # inside bareValue? Hjson # starts comment only if... keep simple break for " #"
            self.i+=1
        raw=self.s[start:self.i].strip()
        # strip trailing comment for // or # if preceded by space?
        # parse scalars
        if raw=="true": return True
        if raw=="false": return False
        if raw=="null": return None
        # numbers
        if re.fullmatch(r'-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?', raw or ""):
            try:
                return float(raw) if any(ch in raw for ch in ".eE") else int(raw)
            except: pass
        return raw

def parse_hjson(text, path):
    try:
        return HParser(text).parse()
    except HjsonError as e:
        # str(e) already shaped
        raise BadConfig(f'Bad configuration file "{path}" : unable to parse Hjson: {e}')

class BadConfig(Exception): pass

def parse_toml_simple(text):
    # limited TOML parser
    root={}; cur=root
    def parse_val(v):
        v=v.strip()
        if v.startswith('"') and v.endswith('"') and len(v)>=2:
            try: return json.loads(v)
            except: return v[1:-1]
        if v.startswith("'") and v.endswith("'"): return v[1:-1]
        if v=="true": return True
        if v=="false": return False
        if v.startswith("[") and v.endswith("]"):
            inner=v[1:-1].strip()
            if not inner: return []
            # split top commas naive
            parts=[]; depth=0; inq=None; curp=""
            for ch in inner:
                if inq:
                    curp+=ch
                    if ch==inq: inq=None
                elif ch in "\"'": inq=ch; curp+=ch
                elif ch in "[{": depth+=1; curp+=ch
                elif ch in "]}": depth-=1; curp+=ch
                elif ch=="," and depth==0: parts.append(curp); curp=""
                else: curp+=ch
            if curp.strip(): parts.append(curp)
            return [parse_val(p) for p in parts]
        if v.startswith("{") and v.endswith("}"):
            inner=v[1:-1]; d={}
            for part in inner.split(","):
                if "=" in part:
                    k,val=part.split("=",1); d[k.strip().strip('"\'')]=parse_val(val)
            return d
        try: return int(v)
        except: pass
        try: return float(v)
        except: pass
        return v
    for rawline in text.splitlines():
        line=rawline.strip()
        if not line or line.startswith("#"): continue
        if line.startswith("[") and line.endswith("]"):
            path=line[1:-1].strip(); cur=root
            for part in path.split("."):
                cur=cur.setdefault(part.strip(),{})
            continue
        if "=" in line:
            k,v=line.split("=",1); k=k.strip().strip('"\'')
            # dotted keys
            parts=k.split("."); target=cur
            for p in parts[:-1]: target=target.setdefault(p.strip(),{})
            target[parts[-1].strip()]=parse_val(v)
    return root

def load_config_file(path):
    # returns dict; raises errors with original messages (printed by caller)
    p=Path(path)
    if not p.is_file():
        raise IOError("No such file or directory (os error 2)")
    ext=p.suffix.lower()
    if ext not in (".hjson",".toml"):
        raise BadConfig(f'Bad configuration: unexpected file extension in "{path}"')
    text=p.read_text(encoding="utf-8", errors="surrogateescape")
    if ext==".hjson":
        data=parse_hjson(text, str(path))
    else:
        try:
            data=parse_toml_simple(text)
        except Exception as e:
            raise BadConfig(f'Bad configuration file "{path}" : unable to parse TOML: {e}')
    if not isinstance(data, dict): data={}
    return data

def merge_config(dst, src):
    for k,v in src.items():
        if k=="verbs" and isinstance(v,list) and isinstance(dst.get(k),list):
            dst[k]=dst[k]+v
        elif k=="imports":
            # do not merge as data, handled by loader
            continue
        elif isinstance(v,dict) and isinstance(dst.get(k),dict):
            nd=dict(dst[k]); nd.update(v); dst[k]=nd
        else:
            dst[k]=v
    return dst

# Terminal luma: unknown -> dark import default
def load_configs(paths, base_for_imports=None):
    cfg={}
    verbs=[]
    skin={}
    imported_files=[]
    def process(data, file_path):
        nonlocal cfg, skin
        imports=data.pop("imports",[]) if isinstance(data,dict) else []
        # verbs extracted
        if "verbs" in data:
            v=data.pop("verbs")
            if isinstance(v,list): verbs.extend(v)
        if "skin" in data:
            s=data.pop("skin")
            if isinstance(s,dict): skin.update(s)
        merge_config(cfg, data)
        # process imports in order
        fdir=Path(file_path).parent if file_path else Path(".")
        if isinstance(imports, (str,)): imports=[imports]
        if isinstance(imports,list):
            for imp in imports:
                fname=None; cond_ok=True
                if isinstance(imp,str): fname=imp
                elif isinstance(imp,dict):
                    fname=imp.get("file")
                    luma=imp.get("luma")
                    # dark/unknown condition: only include if luma contains dark/unknown or is dark/unknown string
                    if luma is not None:
                        vals=[luma] if isinstance(luma,str) else list(luma)
                        if not any(str(x) in ("dark","unknown") for x in vals): cond_ok=False
                if fname and cond_ok:
                    ipath=fdir/fname
                    if not ipath.is_file():
                        raise IOError("No such file or directory (os error 2)")
                    idata=load_config_file(str(ipath))
                    imported_files.append(str(ipath))
                    process(idata, str(ipath))
    for path in paths:
        data=load_config_file(path)
        imported_files.append(str(path))
        process(data, str(path))
    cfg["_verbs"]=verbs
    cfg["_skin"]=skin
    cfg["_imported_files"]=imported_files
    return cfg

