NAMED_COLORS={
    "black":0,"darkgrey":8,"darkgray":8,"red":9,"darkred":1,"green":10,"darkgreen":2,
    "yellow":11,"darkyellow":3,"blue":12,"darkblue":4,"magenta":13,"darkmagenta":5,
    "cyan":14,"darkcyan":6,"white":15,"grey":7,"gray":7,
}
def parse_color_token(tok):
    if tok is None: return None
    t=str(tok).strip()
    low=t.lower()
    if low in ("none",""): return None
    if low.startswith("gray(") or low.startswith("grey("):
        try: return ("ansi",232+int(t[t.find("(")+1:t.find(")")]))
        except: return None
    if low.startswith("ansi("):
        try: return ("ansi",int(t[t.find("(")+1:t.find(")")]))
        except: return None
    if low.startswith("rgb("):
        try:
            nums=[int(x) for x in t[t.find("(")+1:t.find(")")].split(",")]
            return ("rgb",tuple(nums))
        except: return None
    if low.startswith("#") and len(low)==7:
        try: return ("rgb",(int(low[1:3],16),int(low[3:5],16),int(low[5:7],16)))
        except: return None
    if low in NAMED_COLORS: return ("ansi",NAMED_COLORS[low])
    return None

class Style:
    __slots__=("fg","bg","bold","italic","underline","dim","reverse","strike")
    def __init__(self, fg=None,bg=None,bold=False,italic=False,underline=False,dim=False,reverse=False,strike=False):
        self.fg=fg; self.bg=bg; self.bold=bold; self.italic=italic; self.underline=underline; self.dim=dim; self.reverse=reverse; self.strike=strike
    def ansi_prefix(self):
        parts=[]
        if self.bold: parts.append("1")
        if self.dim: parts.append("2")
        if self.italic: parts.append("3")
        if self.underline: parts.append("4")
        if self.reverse: parts.append("7")
        if self.strike: parts.append("9")
        if self.fg is not None:
            kind,val=self.fg
            if kind=="ansi": parts.append(f"38;5;{val}")
            else: parts.append(f"38;2;{val[0]};{val[1]};{val[2]}")
        if self.bg is not None:
            kind,val=self.bg
            if kind=="ansi": parts.append(f"48;5;{val}")
            else: parts.append(f"48;2;{val[0]};{val[1]};{val[2]}")
        if not parts: return ""
        return "\x1b["+";".join(parts)+"m"
    def apply(self,text, colored=True):
        if not colored or not text: return text
        pre=self.ansi_prefix()
        if not pre: return text
        # original often emits fg then bg separate but combined equivalent for terminals
        return pre+text+"\x1b[0m"

def parse_skin_style(value):
    # value like "gray(22) none  / gray(20) none" or "ansi(110) None bold"
    if not isinstance(value,str): return Style()
    first=value.split("/")[0].strip()
    # tokens: color tokens may contain parentheses; split by whitespace
    toks=first.split()
    fg=None; bg=None; bold=italic=underline=False; dim=False
    colors=[]
    attrs=[]
    for tok in toks:
        low=tok.lower()
        if low in ("bold",): bold=True
        elif low in ("italic",): italic=True
        elif low in ("underlined","underline","underlined."): underline=True
        elif low in ("dim",): dim=True
        else: colors.append(tok)
    if len(colors)>=1: fg=parse_color_token(colors[0])
    if len(colors)>=2: bg=parse_color_token(colors[1])
    return Style(fg,bg,bold,italic,underline,dim)

