# ---------------------------------------------------------------- filesystem / gitignore
def find_git_root(start):
    p=Path(start)
    while True:
        if (p/".git").exists(): return p
        if p.parent==p: return None
        p=p.parent

class IgnoreRule:
    __slots__=("base","pattern","neg","dir_only","anchored")
    def __init__(self, base, pattern):
        self.base=Path(base); self.neg=pattern.startswith("!")
        if self.neg: pattern=pattern[1:]
        self.dir_only=pattern.endswith("/")
        if self.dir_only: pattern=pattern[:-1]
        self.anchored=("/" in pattern)
        if pattern.startswith("/"): pattern=pattern[1:]; self.anchored=True
        self.pattern=pattern
    def matches(self, path, is_dir):
        if self.dir_only and not is_dir: return False
        try: rel=str(Path(path).relative_to(self.base))
        except Exception: return False
        pat=self.pattern
        if self.anchored:
            return fnmatch_path(pat, rel)
        else:
            # match any suffix component sequence / basename
            parts=rel.split("/")
            if "/" in pat:
                # match a suffix path
                for i in range(len(parts)):
                    if fnmatch_path(pat, "/".join(parts[i:])): return True
                return False
            else:
                return any(fnmatch.fnmatchcase(part, pat) for part in parts)

def fnmatch_path(pat, s):
    # translate gitignore-ish fnmatch with **, *, ?
    import fnmatch as _fm
    # Python fnmatch allows * to cross / (it uses os.path but fnmatchcase translates * to .*), which approximates ** too.
    return _fm.fnmatchcase(s, pat)

def load_ignore_rules(root):
    rules=[]
    git_root=find_git_root(root)
    start=git_root if git_root else Path(root)
    # gather .ignore/.gitignore from start down? Broader: parents of root up to git_root, and global exclude
    dirs=[]
    p=Path(root)
    chain=[]
    cur=p
    while True:
        chain.append(cur)
        if git_root and cur==git_root: break
        if cur.parent==cur: break
        cur=cur.parent
        if git_root is None and len(chain)>20: break
    chain.reverse()
    for d in chain:
        # .ignore has priority over .gitignore -> append later
        for fname in [".gitignore",".ignore"]:
            f=d/fname
            if f.is_file():
                try:
                    for line in f.read_text(errors="ignore").splitlines():
                        line=line.strip()
                        if not line or line.startswith("#"): continue
                        rules.append(IgnoreRule(d,line))
                except Exception: pass
    if git_root:
        excl=git_root/".git"/"info"/"exclude"
        if excl.is_file():
            try:
                for line in excl.read_text(errors="ignore").splitlines():
                    line=line.strip()
                    if line and not line.startswith("#"): rules.append(IgnoreRule(git_root,line))
            except Exception: pass
    # per-directory rules are loaded during walk in Node expansion (stored dynamically)
    return rules, git_root

