# ---------------------------------------------------------------- patterns
def normalize_text(s):
    # casefold + strip diacritics
    import unicodedata
    s=unicodedata.normalize("NFKD", s)
    s="".join(c for c in s if not unicodedata.combining(c))
    return s.lower()

def fuzzy_align(pattern, text):
    """Return (score, indices set) or None. Best subsequence alignment via DP maximizing bonuses."""
    p=normalize_text(pattern); t_raw=text; t=normalize_text(text)
    if p=="": return (0,set())
    # DP for max score alignment: dp[i][j]
    # implement greedy/Dynamic with backtracking using recursion+cache on (pi,ti,prev_consecutive)
    from functools import lru_cache
    # iterative search for best alignment with simple scoring using recursion and memo returning best score and indices
    best=[None]
    # Use recursion with pruning; texts are paths/names short
    sys.setrecursionlimit(10000)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def rec(pi, ti, prev_match):
        if pi==len(p):
            return (0, ())
        if ti==len(t):
            return None
        # prune remaining
        if len(p)-pi > len(t)-ti:
            # still may skip? no, need at least...
            pass
        best_local=None
        # skip char
        skipped=rec(pi, ti+1, False)
        if skipped is not None:
            best_local=(skipped[0]- (1 if ti>0 else 0), skipped[1])
        if p[pi]==t[ti]:
            nxt=rec(pi+1, ti+1, True)
            if nxt is not None:
                score=nxt[0]+10
                if prev_match: score+=15
                # word start bonus
                if ti==0 or t[ti-1] in "/._- \\": score+=18
                if t_raw[ti].lower()!=t_raw[ti] and False: pass
                # exact case bonus
                if pi<len(pattern) and pattern[pi]==t_raw[ti]: score+=2
                # distance from start penalty small already via skips
                cand=(score, (ti,)+nxt[1])
                if best_local is None or cand[0]>best_local[0]: best_local=cand
        return best_local
    res=rec(0,0,False)
    if res is None: return None
    score=res[0]
    # normalize by length of text (shorter texts score higher for same match)
    score = score*10 - len(t)
    # bonus if pattern appears as contiguous substring
    if p in t: score+=120 - t.find(p)
    return (score, set(res[1]))

