                        val=node.deep_size() if node.is_dir else (node.size_bytes if node.is_file else 0)
                        ratio=(val/root_deep_size) if root_deep_size else 0
                        bar=gauge_bar(ratio,10)
                        # style for bar in color mode: pick good_to_bad based on ratio
                        idx=min(9,int(ratio*10)) if ratio>0 else 0
                        bstyle=skin.styles.get(f"good_to_bad_{idx}", skin.get("default")) if ratio>0 else skin.get("default")
                        segs.append((bar.ljust(10), bstyle))
                        segs.append((" ", skin.get("default")))
            elif col=="date":
                if disp.show_dates or disp.sort_mode=="date":
                    txt=date_text.get(id(dn),"")
                    segs.append((txt, skin.get("dates")))
                    segs.append((" ", skin.get("default")))
            elif col=="permission" or col=="perm":
                if disp.show_permissions:
                    ps=perm_string(node) if not dn.is_unlisted else " "*9
                    # each char style simplified: whole with perm_r-ish? Use one style for string to preserve plain; color differences per char would be normalized by tmux? Keep segmented
                    # segmented chars
                    for ch in ps:
                        if ch=="r": sty=skin.get("perm_r")
                        elif ch=="w": sty=skin.get("perm_w")
                        elif ch=="x": sty=skin.get("perm_x")
                        else: sty=skin.get("perm__")
                        segs.append((ch,sty))
                    segs.append((" ",skin.get("default")))
                    o,g=owner_group(node) if not dn.is_unlisted else ("","")
                    segs.append((o.ljust(owner_width), skin.get("owner")))
                    segs.append((" ",skin.get("default")))
                    segs.append((g, skin.get("group")))
                    segs.append((" ",skin.get("default")))
            elif col=="count":
                if disp.show_counts or disp.sort_mode=="count":
                    txt=count_text.get(id(dn),"")
                    segs.append((txt.rjust(count_width), skin.get("count")))
                    segs.append((" ",skin.get("default")))
            elif col=="branch":
                # branch prefix
                for is_last_anc in anc:
                    segs.append(("   " if is_last_anc else "│  ", skin.get("tree")))
                segs.append(("└──" if last else "├──", skin.get("tree")))
            elif col=="name":
                if dn.is_unlisted:
                    segs.append((f"{dn.unlisted_count} unlisted", skin.get("pruning")))
                else:
                    label=node_label(node,label_mode)
                    # name style
                    if node.is_link:
                        namesty=skin.get("link")
                    elif node.is_dir:
                        namesty=skin.get("directory")
                    elif node.is_file and node.lstat and (node.lstat.st_mode & stat.S_IXUSR):
                        namesty=skin.get("exe")
                    elif node.error:
                        namesty=skin.get("file_error")
                    else:
                        namesty=skin.get("file")
                    # match indices: node.match_indices refers to target text (name or subpath). Label may be that.
                    idxs=node.match_indices if node.match_indices else set()
                    # only apply indices if label equals target (approx: if label_mode path, indices for path; if name and an elementary is name-like, but node.match_indices could be path-based for default fuzzy; when label=name in composite with content, skip)
                    # Determine if we should highlight: use indices when patterned and not content
                    if idxs:
                        # build per char segments
                        for pos,ch in enumerate(label):
                            sty=skin.get("char_match") if pos in idxs else namesty
                            # preserve directory bold: char_match style in skin has no bold - original likely overrides? We'll merge bold from namesty
                            if pos in idxs and namesty.bold and not sty.bold:
                                sty=Style(sty.fg,sty.bg,True,sty.italic,sty.underline)
                            segs.append((ch,sty))
                    else:
                        segs.append((label, namesty))
                    if node.is_link and node.link_target_abs is not None:
                        segs.append((" -> ", skin.get("link")))
                        # target style
                        if node.broken: tsty=skin.get("file_error")
                        elif node.is_dir: tsty=skin.get("directory")
                        else: tsty=skin.get("file")
                        segs.append((node.link_target_abs, tsty))
                    # truncated?
                    truncated=False
                    if dn.node is node:
                        # display children vs full filtered children
                        if (not dn.children and not dn.placeholder) and node.children:
                            truncated=True
                        if getattr(node,"has_hidden_children",False): truncated=True
                    if truncated:
                        segs.append((" …", skin.get("pruning")))
                    if node.content_extract:
                        segs.append(("   ", skin.get("default")))
                        segs.append((node.content_extract.rstrip("\n"), skin.get("content_extract")))
                # trailing space for print accuracy (caller decides to keep)
                segs.append((" ", skin.get("default")))
            elif col=="device_id":
                pass
        lines.append(RLine(node,dn,segs))
    return lines

