# ---------------------------------------------------------------- panels & app
class Panel:
    def __init__(self, app, root_path, disp=None, kind="tree"):
        self.app=app; self.kind=kind
        self.root_path=Path(root_path)
        self.disp=disp.clone() if disp else app.base_disp.clone()
        self.input_text=""; self.cursor=0
        self.pattern_str=""; self.pattern=None; self.label_mode="name"
        self.root_node=None; self.droot=None; self.lines=[]; self.selection_idx=0; self.selected_path=None
        self.scroll=0; self.history=[]
        self.status_message=None; self.status_is_error=False
        self.git_status=None
        self.preview_file=None; self.preview_mode="text"; self.preview_lines=[]; self.preview_title=""; self.preview_right=""; self.preview_scroll=0
        self.help_scroll=0; self.fs_rows=[]; self.staging=False
        self.initial_file=None
        if kind=="tree": self.rebuild(selection_path=str(root_path))
    # ---------- tree building
    def rebuild(self, selection_path=None, keep_selection=True):
        app=self.app
        # git status object
        self.git_status=GitStatus(self.root_path) if (self.disp.show_git_info or self.disp.git_status_only) else GitStatus(self.root_path) if app.needs_git(self) else None
        # pattern
        self.pattern=None
        if self.pattern_str:
            try: self.pattern=PatternParser(self.pattern_str).parse()
            except Exception: self.pattern=None
            # label mode
            if self.pattern:
                elems=self.pattern.elementaries()
                if any(e.target=="content" for e in elems): self.label_mode="name"
                elif elems and all(e.target=="path" for e in elems): self.label_mode="path"
                elif elems: self.label_mode="name" if elems[0].target=="name" else ("path" if elems[0].target=="path" else "name")
        builder_disp=self.disp
        # git status mode: include hidden for building
        if self.disp.git_status_only:
            builder_disp=self.disp.clone(); builder_disp.show_hidden=True
        builder=TreeBuilder(self.root_path, builder_disp, app.cfg, self.pattern, self.git_status)
        self.root_node=builder.build()
        # display budget
        budget = app.tree_budget(self)
        self.droot=build_display_tree(self.root_node, budget, self.disp.trim_root)
        self.lines=render_lines(self.droot, self.disp, app.skin, self.git_status, self.label_mode, app.cfg)
        # selection determination
        prev_path=selection_path if selection_path is not None else (self.selected_path if keep_selection else None)
        idx=None
        if self.pattern is not None:
            # best score among non-root retained nodes
            best=None; best_idx=None
            for i,line in enumerate(self.lines):
                if i==0: continue
                sc=line.node.match_score
                if sc is not None:
                    if best is None or sc>best: best=sc; best_idx=i
            # best_idx could correspond to an ancestor (kept non-matching) with score None; ignore
            if best_idx is not None: idx=best_idx
        if idx is None and prev_path:
            for i,line in enumerate(self.lines):
                if str(line.node.path)==str(prev_path) and not line.is_unlisted: idx=i; break
        if idx is None:
            idx=0
        # if pattern and no matches: original print keeps root but UI ??? Keep root as selection for our purposes, but lines are there.
        self.selection_idx=idx
        if self.lines: self.selected_path=str(self.lines[idx].node.path)
        self.clamp_scroll()
    def clamp_scroll(self):
        area=self.app.tree_area_height()
        if self.selection_idx < self.scroll: self.scroll=self.selection_idx
        if self.selection_idx >= self.scroll+area: self.scroll=self.selection_idx-area+1
        if self.scroll<0: self.scroll=0
        maxscroll=max(0,len(self.lines)-area)
        # In original, display tree already limited; scrolling beyond is possible when selecting last line. Keep scroll bounded by line count.
        if self.scroll>maxscroll and len(self.lines)>area: 
            # allow scroll to keep selection visible but not beyond max
            self.scroll=maxscroll
    def selected_line(self):
        if not self.lines: return None
        self.selection_idx=max(0,min(self.selection_idx,len(self.lines)-1))
        return self.lines[self.selection_idx]
    def selected_node(self):
        l=self.selected_line(); return l.node if l else None
    def snapshot(self):
        return dict(root=str(self.root_path), selected=self.selected_path, input=self.input_text, pattern=self.pattern_str, disp=self.disp.clone(), kind=self.kind, preview_file=str(self.preview_file) if self.preview_file else None)
    def restore(self,snap):
        self.kind=snap.get("kind","tree"); self.root_path=Path(snap["root"]); self.disp=snap["disp"].clone(); self.input_text=snap.get("input",""); self.cursor=len(self.input_text); self.pattern_str=snap.get("pattern","")
        if self.kind=="tree": self.rebuild(selection_path=snap.get("selected"))
    def push_history(self):
        self.history.append(self.snapshot())
        if len(self.history)>100: self.history.pop(0)
    def apply_input_pattern(self):
        pat,verb=split_input(self.input_text)
        # if input starts with verb separator, pattern remains existing pattern_str
        if self.input_text.startswith(":") or self.input_text.startswith(" "):
            # pattern unchanged
            pass
        else:
            self.pattern_str=pat
        self.rebuild(keep_selection=True)
        # after pattern change, if no verb, selection goes to best match (rebuild does if pattern)
    # ---------- preview builders
    def open_preview_for_selection(self, mode=None):
        node=self.selected_node()
        if node is None: return None
        return self.app.open_preview(self, node, mode)

