        self.verb_output_path=opts.get("verb_output")
        self.outcmd_path=opts.get("outcmd")
        self.last_pattern=""
        self.watching=False
        self.panel_widths=None  # list ratios?
        self.status_override=None
    def needs_git(self,panel):
        return False
    def tree_area_height(self):
        return max(1,self.height-2)
    def tree_budget(self,panel):
        if panel.disp.trim_root:
            return max(1,self.height-2)
        return max(1,self.height-1)
    def active_panel(self):
        if not self.panels: return None
        self.active_idx=max(0,min(self.active_idx,len(self.panels)-1))
