    panel.root_path=parent; panel.pattern_str=""; panel.input_text=""; panel.cursor=0
    panel.rebuild(selection_path=old_root)
    return VerbResult("ok")

def open_os_file(app,node):
    # detached open (like xdg-open), silent
    try:
