    except Exception: pass

def select_next_match(app,panel,dirn):
    if not panel.lines: return VerbResult("ok")
    # matching nodes are those with matched flag (if pattern) else move selection by 1
    idxs=[i for i,l in enumerate(panel.lines) if l.node.matched]
    if not idxs:
        panel.move_selection(dirn); return VerbResult("ok")
    cur=panel.selection_idx
