def shell_quote_path(p):
    s=str(p)
    if s and re.fullmatch(r'[A-Za-z0-9_@%+=:,./-]+', s): return s
    return '"' + s.replace('\\','\\\\').replace('"','\\"').replace('$','\\$').replace('`','\\`') + '"'

def resolve_arg_path(base, arg):
    if arg is None: return None
    a=os.path.expandvars(os.path.expanduser(str(arg)))
    p=Path(a)
    if not p.is_absolute(): p=Path(base)/p
    # canonicalize: resolve if possible
    try: return str(p.resolve())
    except Exception: return str(p)

def selection_directory(node):
    if node is None: return Path.cwd()
    return node.path if node.is_dir else node.path.parent

def expand_placeholders(template, app, panel, verb, user_args):
    node=panel.selected_node()
    if node is None: node=panel.root_node
    file_path=str(node.path) if node else ""
    parent=str(node.path.parent) if node else ""
    directory=str(selection_directory(node)) if node else ""
    name=node.name if node else ""
    # file stem/ext like Rust Path
    if "." in name[1:]:
        stem,ext=name.rsplit(".",1); dotext="."+ext
    elif name.startswith(".") and len(name)>1:
        # .hidden: stem .hidden? Rust file_stem for .hidden is .hidden, ext None
        stem=name; ext=""; dotext=""
    else:
        stem=name; ext=""; dotext=""
    # other panel
    other_file=""; other_parent=""; other_dir=""
    others=[p for p in app.panels if p is not panel]
    if others:
        on=others[-1].selected_node()
        if on:
            other_file=str(on.path); other_parent=str(on.path.parent); other_dir=str(selection_directory(on))
    git_root=""
    try:
        gr=find_git_root(panel.root_path)
        if gr: git_root=str(gr)
    except Exception: pass
    std={"file":file_path,"parent":parent,"directory":directory,"file-name":name,"file-stem":stem,"file-extension":ext,"file-dot-extension":dotext,"other-panel-file":other_file,"other-panel-parent":other_parent,"other-panel-directory":other_dir,"git-root":git_root,"root":str(panel.root_path),"line":"1"}
    def repl(m):
        key=m.group(1); modifier=m.group(2)
        if key in user_args:
            val=user_args[key]
            if modifier=="path-from-parent":
                return resolve_arg_path(parent, val)
            if modifier=="path-from-directory":
                return resolve_arg_path(directory, val)
            return str(val)
        if key in std: return std[key]
        return m.group(0)
    return re.sub(r'\{([^}:]+)(?::([^}]+))?\}', repl, template)

def tokenize_template(template):
    # split respecting quotes, returning tokens with quotes removed
    tokens=[]; cur=""; inq=None; esc=False
    for ch in template:
        if esc: cur+=ch; esc=False; continue
        if ch=="\\": cur+=ch; esc=True; continue  # keep backslash for placeholder expansion? preserve char as escaped later
        if inq:
            if ch==inq: inq=None
            else: cur+=ch
            continue
        if ch in "\"'": inq=ch; continue
        if ch.isspace():
            if cur: tokens.append(cur); cur=""
            continue
        cur+=ch
    if cur: tokens.append(cur)
    return tokens

class VerbResult:
    def __init__(self, kind="ok", message=None, is_error=False):
        self.kind=kind; self.message=message; self.is_error=is_error

def focus_directory(app,panel,dir_path, keep_pattern=False, select_path=None):
    dir_path=Path(dir_path)
    try: dir_path=Path(dir_path.resolve())
    except Exception: pass
    panel.push_history()
    panel.root_path=dir_path
    if not keep_pattern:
        panel.pattern_str=""; panel.input_text=""; panel.cursor=0
    panel.rebuild(selection_path=str(select_path) if select_path else str(dir_path))
    return VerbResult("ok")

def execute_verb_text(app,panel,verb_text, runner=None):
    original=verb_text
    verb_text=verb_text.strip()
    new_panel=False
    if verb_text.startswith("!"):
        new_panel=True; verb_text=verb_text[1:].lstrip()
    if not verb_text:
        return VerbResult("missing")
    parts=verb_text.split(None,1)
    typed=parts[0]; remainder=parts[1] if len(parts)>1 else ""
    if typed.endswith("!") and len(typed)>1:
        new_panel=True; typed=typed[:-1]
    verb=find_verb(app.verbs, typed)
    if verb is None:
        return VerbResult("notfound", f'verb not found: "{typed}"', True)
    node=panel.selected_node()
    # Special cd/open_leave choice
    chosen_name=verb.name
    # If typed matched cd but selection is file, treat as notfound as original
    if verb.name=="cd" and node is not None and not node.is_dir:
        return VerbResult("notfound", f'verb not found: "{typed}"', True)
    if verb.name=="open_leave" and node is not None and node.is_dir:
        chosen_name="cd"
    # custom verbs overriding builtins: configured verb with same name as internal but kind external/configured_internal takes precedence because build order: find_verb returns first matching which may be configured; if verb.configured and verb.name in ("edit","create","git_diff","backup","terminal"): proceed external.
    # Argument map
    user_args={}
    args_needed=list(verb.invocation_args)
    if args_needed:
        if not remainder:
            # verbs focus/select etc can have optional args handled below for some internal
            optional={"focus","open_preview","close_preview","toggle_preview","preview_text","preview_binary","preview_image","preview_tty"}
            if verb.name not in optional and verb.kind not in ("configured_internal",):
                # Some internals like write_output with no text should still execute? original writes empty? but generally missing.
                # focus has optional
                return VerbResult("missing")
        else:
            if len(args_needed)==1:
                user_args[args_needed[0]]=remainder
            else:
                toks=remainder.split()
                for i,an in enumerate(args_needed):
                    if i < len(toks): user_args[an]=toks[i] if i<len(args_needed)-1 else " ".join(toks[i:])
    # configured internal sequence/name
    if verb.kind=="configured_internal":
        execstr=verb.execution.strip()
        if execstr.startswith(":"):
            return execute_command_string(app,panel,execstr,runner)
        else:
            # treat as invoking another verb by name
            return execute_verb_text(app,panel,execstr + ((" "+remainder) if remainder else ""), runner)
    if verb.kind=="external":
        # chmod choose template based on dir
        template=verb.execution
        if verb.name=="chmod" and node is not None and node.is_dir:
            template="chmod -R {args} {file}"
        expanded=expand_placeholders(template, app,panel,verb,user_args)
        # token expansion
        raw_tokens=tokenize_template(expanded)
        argv=[]
        for tok in raw_tokens:
            # $VAR tokens
            if tok.startswith("$") and " " in os.environ.get(tok[1:],""):
                argv.extend(os.environ[tok[1:]].split())
            else:
                argv.append(os.path.expandvars(tok))
        if not argv: return VerbResult("missing")
        display=" ".join(argv)
        if runner:
            code=runner(argv, display, verb)
            # runner handles leave/stay
            if verb.leave_broot:
                return VerbResult("quit")
            # refresh
            panel.rebuild(keep_selection=True)
            if code not in (0,None):
                return VerbResult("error", f"command exited with code {code}", True)
            return VerbResult("ok")
        else:
            return VerbResult("ok")
    # internal verbs
    name=verb.name
    try:
        return execute_internal(app,panel,verb,name,remainder,user_args,runner,new_panel)
    except FileNotFoundError:
        return VerbResult("error","IO Error : No such file or directory (os error 2)",True)
    except Exception as e:
        return VerbResult("error", str(e), True)

def execute_internal(app,panel,verb,name,remainder,user_args,runner,new_panel):
