        panel.input_text=segment; panel.cursor=len(segment)
        if result.message: panel.status_message=result.message; panel.status_is_error=result.is_error
        return result
    if result.kind=="quit":
        return result
    # successful staying verb: remove verb part from input, keep pattern (if pattern came from this segment). If starts_verb, input unchanged.
    panel.status_message=None
