# ---------------------------------------------------------------- key handling
def insert_text(panel,text):
    panel.input_text=panel.input_text[:panel.cursor]+text+panel.input_text[panel.cursor:]
    panel.cursor+=len(text)
    after_input_edit(panel)

def after_input_edit(panel):
    panel.status_message=None
    app=panel.app
    if panel.kind=="tree":
        pat,verb=split_input(panel.input_text)
        if not (panel.input_text.startswith(":") or panel.input_text.startswith(" ")):
            panel.pattern_str=pat
            if pat: app.last_pattern=pat
        panel.rebuild()
    elif panel.kind=="help":
        pat,verb=split_input(panel.input_text)
        if not (panel.input_text.startswith(":") or panel.input_text.startswith(" ")):
            panel.pattern_str=pat
    elif panel.kind=="preview":
        pass

def handle_enter(app,panel,runner):
    if panel.kind=="help":
        # open main config file with editor verb if configured? Execute 'edit' on config file if possible
        # simplified: quit? No: attempt open with xdg/open editor environment via external edit verb on a temporary tree? Skip action.
