    """Return DNode tree trimmed to max_lines as per our simulated builder."""
    if max_lines is None or max_lines<=0: max_lines=1
    total=full_line_count(root)
    if total<=max_lines:
        root_dn=DNode(root)
        def fill(dn):
            for c in dn.node.children:
                cd=DNode(c); dn.children.append(cd); fill(cd)
        fill(root_dn)
        return root_dn
    def simulate(budget, skip_mode):
        root_dn=DNode(root); lines=1
        def add_child(dn, child_node):
            cd=DNode(child_node); dn.children.append(cd); return cd
        def all_display_dirs():
            dirs=[]
            def rec(dn,depth):
                if dn.node.is_dir: dirs.append((depth,dn))
                for c in dn.children: rec(c,depth+1)
            rec(root_dn,0)
            by={}
            for depth,dn in dirs: by.setdefault(depth,[]).append(dn)
            ordered=[]
            for depth in sorted(by): ordered.extend(reversed(by[depth]))
            return ordered
        def find_first_partial(dn):
            if dn.node is not root and dn.placeholder: return dn
            for c in dn.children:
                r=find_first_partial(c)
                if r: return r
            return None
        changed=True
        while lines<budget and changed:
            changed=False
            candidates=all_display_dirs()
            for dn in candidates:
                if lines>=budget: break
                node=dn.node
                if dn.done: continue
                child_nodes=node.children
                if not dn.started:
                    dn.started=True; changed=True
                    if len(child_nodes)==0:
