                    if node is root and trim_root and len(child_nodes) > (budget-lines):
                        if budget>=4:
                            visible=child_nodes[1:1+max(0,budget-3)]
                            for c in visible: add_child(dn,c)
                            lines+=len(visible); dn.next_idx=1+len(visible); dn.unlisted_count=len(child_nodes)-len(visible); dn.placeholder=True; lines+=1
                        elif budget==3:
                            if len(child_nodes)>1: add_child(dn, child_nodes[1]); lines+=1
                            dn.next_idx=2; dn.unlisted_count=0; dn.placeholder=False
                        dn.done=True; continue
                    if node is root:
                        add_count=min(len(child_nodes), budget-lines)
                        for c in child_nodes[:add_count]: add_child(dn,c)
                        lines+=add_count; dn.next_idx=add_count; dn.done=True; continue
                    if lines+len(child_nodes)<=budget:
