                                if dn.next_idx>=len(child_nodes): continue
                        add_child(dn, child_nodes[dn.next_idx]); dn.next_idx+=1; dn.unlisted_count-=1; lines+=1; changed=True
                        if dn.unlisted_count<=0:
                            dn.placeholder=False; dn.unlisted_count=0; dn.done=True; lines-=1
                        continue
        return root_dn
    def has_nonroot_placeholder(dn):
        if dn.node is not root and dn.placeholder: return True
        return any(has_nonroot_placeholder(c) for c in dn.children)
    result=simulate(max_lines, skip_mode=False)
    if has_nonroot_placeholder(result):
        result=simulate(max(1,max_lines-1), skip_mode=True)
    return result

